function Honghu.jaff_rhs!(du, ::Network, nden, photden, rflux, tgas, c_hat)
    # $$JAFF REPEAT idx, rhs, cse IN rhses { USE honghu }
    cse0 = 6.30000010082044e-18 * c_hat .* nden[0+1]
    cse1 = cse0 .* photden[0+1]
    cse2 = cse1 - 2.59e-13 * nden[1+1] .* nden[2+1]
    du[1] = -cse2
    du[2] = cse2
    du[3] = cse2
    du[4] = 0
    du[5] = -cse1
    du[6] = -cse0 .* rflux[0+1]
    # $$JAFF END
    return nothing
end

function Honghu.jaff_jacobian!(J, ::Network, nden, photden, rflux, tgas, c_hat)
    # $$JAFF REPEAT idx, expr, cse IN jacobian { USE honghu }
    cse0 = 6.30000010082044e-18 * c_hat
    cse1 = cse0 .* photden[0+1]
    cse2 = -cse1
    cse3 = 2.59e-13 * nden[2+1]
    cse4 = 2.59e-13 * nden[1+1]
    cse5 = cse0 .* nden[0+1]
    cse6 = -cse5
    cse7 = -cse3
    cse8 = -cse4
    J[1, 1] = cse2
    J[1, 2] = cse3
    J[1, 3] = cse4
    J[1, 5] = cse6
    J[2, 1] = cse1
    J[2, 2] = cse7
    J[2, 3] = cse8
    J[2, 5] = cse5
    J[3, 1] = cse1
    J[3, 2] = cse7
    J[3, 3] = cse8
    J[3, 5] = cse5
    J[5, 1] = cse2
    J[5, 5] = cse6
    J[6, 1] = -cse0 .* rflux[0+1]
    J[6, 6] = cse6
    # $$JAFF END
    return nothing
end

